--
-- Name: person_debts; Type: VIEW; Schema: public; Owner: konvent
--

CREATE VIEW public.person_debts AS
 SELECT p.id,
    p.first_name,
    p.last_name,
    p.coetus,
    p.konvent,
    ((COALESCE(purchases.total, (0)::numeric) - COALESCE(payments.total, (0)::numeric)) + COALESCE(adjustments.total, (0)::numeric)) AS debt
   FROM (((public.people p
     LEFT JOIN ( SELECT purchases_1.person_id,
            sum(
                CASE
                    WHEN (purchases_1.cash_operation = 'cash_deposit'::text) THEN (- abs(purchases_1.total_price))
                    WHEN (purchases_1.cash_operation = 'cash_withdrawal'::text) THEN abs(purchases_1.total_price)
                    WHEN (purchases_1.affects_debt = true) THEN purchases_1.total_price
                    ELSE (0)::numeric
                END) AS total
           FROM public.purchases purchases_1
          WHERE (purchases_1.is_cancelled = false)
          GROUP BY purchases_1.person_id) purchases ON ((purchases.person_id = p.id)))
     LEFT JOIN ( SELECT payments_1.person_id,
            sum(payments_1.amount) AS total
           FROM public.payments payments_1
          GROUP BY payments_1.person_id) payments ON ((payments.person_id = p.id)))
     LEFT JOIN ( SELECT debt_adjustments.person_id,
            sum(debt_adjustments.amount) AS total
           FROM public.debt_adjustments
          GROUP BY debt_adjustments.person_id) adjustments ON ((adjustments.person_id = p.id)));


ALTER VIEW public.person_debts OWNER TO konvent;

